/**
 * The Coin class represents a gold coin that the player can pick up.
 */
class Coin extends GameEntity {
  /**
   * Creates a collectible.
   * @param {number=} x
   * @param {number=} y
   * @param {number=} z
   * @param {{semanticKey: string, semanticUnits: number, visualUnits: number}=} cargo
   */
  constructor(x, y, z, cargo) {
    super(x, y, z);

    /** @type {?Platform} */
    this.carrier = null;

    /** @type {number} */
    this.pickupSequence = 0;

    /** @type {?string} */
    this.semanticKey = cargo ? cargo.semanticKey : null;

    /** @type {number} */
    this.semanticUnits = cargo ? cargo.semanticUnits : 1;

    /** @type {number} */
    this.worldUnits = cargo ? cargo.visualUnits : 1;
  }

  /**
   * Updates the coin.
   * @override
   */
  update() {
    const dist = this.getDistanceToPlayer();
    if (dist < 1.0) {
      this.health = 0;
      const pickupKey = this.semanticKey ||
          'pickup-' + (++this.pickupSequence);
      if (this.carrier) {
        this.carrier.releasePassenger(this);
      }
      recordInventoryReceipt('pickup', pickupKey, this.semanticUnits);
      coinSequence++;
      lastCoinTime = gameTime;
      playCoinSound();
    } else if (dist < 3) {
      // Move the coin toward the player
      this.pos[0] = 0.9 * this.pos[0] + 0.1 * player.pos[0];
      this.pos[1] = 0.9 * this.pos[1] + 0.1 * player.pos[1];
      this.pos[2] = 0.9 * this.pos[2] + 0.1 * player.pos[2];
    }
  }

  /**
   * Renders the coin.
   * @override
   */
  render() {
    const r = (time % 1.0) * 2 * Math.PI;
    const y = 1.5 + 0.2 * Math.sin(r);
    for (let i = 0; i < this.worldUnits; i++) {
      const m = this.createSphere(COLOR_YELLOW);
      const x = (i - (this.worldUnits - 1) / 2) * 0.7;
      mat4.translate(m, m, vec3.fromValues(x, y, 0));
      mat4.rotateY(m, m, r);
      mat4.scale(m, m, vec3.fromValues(0.5, 0.5, 0.1));
    }
  }
}

/**
 * The Platform class represents something that other entities can stand on.
 * Platforms can be stationary or moving.
 */
class Platform extends GameEntity {
  /**
   * Creates a new particle.
   * @param {number=} x
   * @param {number=} y
   * @param {number=} z
   */
  constructor(x, y, z) {
    super(x, y, z);

    /** @type {number} */
    this.color = COLOR_SILVER;

    /** @const {!vec3} */
    this.scale = vec3.fromValues(1, 1, 1);

    /** @type {!Array.<!vec3>} */
    this.waypoints = [];

    /** @type {number} */
    this.waypointIndex = 0;

    /** @const {!Array.<!Coin>} */
    this.passengers = [];

    /** @const {!vec3} */
    this.previousPosition = vec3.clone(this.pos);

    /** @type {number} */
    this.transportSequence = 0;

    /** @type {boolean} */
    this.deliveryWindow = false;
  }

  /**
   * Updates the platform.
   * @override
   */
  update() {
    vec3.copy(this.previousPosition, this.pos);
    const waypoint = this.updateWaypoints();
    if (waypoint) {
      vec3.subtract(this.velocity, waypoint, this.pos);
      vec3.normalize(this.velocity, this.velocity);
      vec3.scale(this.velocity, this.velocity, 6.0);
      vec3.scaleAndAdd(this.pos, this.pos, this.velocity, dt);
    }
    this.deliveryWindow = this.velocity[1] < -0.1;
    const delta = vec3.subtract(vec3.create(), this.pos, this.previousPosition);
    this.passengers.forEach((passenger) => {
      vec3.add(passenger.pos, passenger.pos, delta);
    });
  }

  /**
   * Couples an entity to this platform's motion.
   * @param {!Coin} passenger
   */
  attachPassenger(passenger) {
    this.passengers.push(passenger);
    passenger.carrier = this;
  }

  /**
   * Completes a platform-relative handoff.
   * @param {!Coin} passenger
   * @return {string}
   */
  releasePassenger(passenger) {
    const receiptKey = 'transport-' + this.transportSequence;
    const index = this.passengers.indexOf(passenger);
    if (index >= 0) {
      this.passengers.splice(index, 1);
    }
    passenger.carrier = null;
    if (this.deliveryWindow) {
      recordInventoryReceipt('transport', receiptKey);
    }
    this.transportSequence++;
    return 'transport-' + this.transportSequence;
  }

  /**
   * Renders the platform.
   * @override
   */
  render() {
    if (this.waypoints.length > 0) {
      // Draw lift
      {
        // Draw yellow base
        const m = buffers[DYNAMIC_CUBES].addInstance(COLOR_YELLOW);
        mat4.multiply(m, m, this.transformMatrix);
