import {createReadStream, existsSync, statSync} from 'node:fs';
import {createServer} from 'node:http';
import {extname, join, normalize} from 'node:path';

const args = process.argv.slice(2);
const value = (name, fallback) => {
  const index = args.indexOf(name);
  return index >= 0 && args[index + 1] ? args[index + 1] : fallback;
};
const host = value('--host', '127.0.0.1');
const port = Number(value('--port', '4173'));
const root = join(process.cwd(), 'dist');
const serviceOrigin = process.env.CUA_SWE_EXTERNAL_SERVICE_ORIGIN ||
    'http://127.0.0.1:4174';
const contentTypes = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
};

createServer(async (request, response) => {
  const requestUrl = new URL(request.url, `http://${request.headers.host}`);
  const requestPath = requestUrl.pathname;
  if (requestPath === '/api/cargo-manifest') {
    try {
      const upstream = await fetch(serviceOrigin + requestUrl.pathname +
          requestUrl.search);
      const body = await upstream.text();
      response.writeHead(upstream.status, {
        'content-type': upstream.headers.get('content-type') ||
            'application/json',
        'cache-control': 'no-store',
      });
      response.end(body);
    } catch (error) {
      response.writeHead(502, {'content-type': 'application/json'});
      response.end(JSON.stringify({error: 'cargo service unavailable'}));
    }
    return;
  }
  const relative = requestPath === '/' ? 'index.html' : requestPath.slice(1);
  const resolved = normalize(join(root, relative));
  if (!resolved.startsWith(root) || !existsSync(resolved) || !statSync(resolved).isFile()) {
    response.writeHead(404);
    response.end('Not found');
    return;
  }
  response.writeHead(200, {
    'content-type': contentTypes[extname(resolved)] || 'application/octet-stream',
    'cache-control': 'no-store',
  });
  createReadStream(resolved).pipe(response);
}).listen(port, host, () => {
  console.log(`Captain Callisto listening on http://${host}:${port}`);
});

/**
 * The Flagpole class represents the flag goal of the level.
 */
class Flagpole extends GameEntity {
  /**
   * Creates a new flagpole.
   * @param {number=} x
   * @param {number=} y
   * @param {number=} z
   */
  constructor(x, y, z) {
    super(x, y, z);
    this.triggered = false;
  }
  /**
   * Updates the flagpole.
   * @override
   */
  update() {
    const dist = this.getDistanceToPlayer();
    if (coins === availableCoins && dist < 2.0 && !this.triggered) {
      playMusic(flagpoleSongData);
      bestTimes[level] = bestTimes[level] ? Math.min(bestTimes[level], gameTime) : gameTime;
      localStorage['callisto-times'] = JSON.stringify(bestTimes);
      addTrophy(`Level ${level}`, `${gameTime.toFixed(1)} sec`);
      stopJetpackSound();
      setMenu(winScreen);
      gameState = GameState.AFTER_LEVEL;
      window.dispatchEvent(new CustomEvent('captaincallisto-level-complete', {
        detail: {level: level, coins: coins, coinsTotal: availableCoins},
      }));
      this.triggered = true;
    }
  }

  /**
   * Renders the flagpole.
   * @override
   */
  render() {
    const r = (time % 1.0) * 2 * Math.PI;
    const y = 4.7 + 0.1 * Math.sin(r);

    // Main flag pole
    {
      const m = this.createSphere(COLOR_SILVER);
      mat4.translate(m, m, vec3.fromValues(0, 2.5, 0));
      mat4.scale(m, m, vec3.fromValues(0.2, 2.5, 0.2));
    }

    // Base
    {
      const m = this.createSphere(COLOR_SILVER);
      mat4.scale(m, m, vec3.fromValues(0.5, 0.5, 0.5));
    }

    // Red ball on top
    {
      const m = this.createSphere(COLOR_RED);
      mat4.translate(m, m, vec3.fromValues(0, y, 0));
      mat4.rotateY(m, m, r);
      mat4.scale(m, m, vec3.fromValues(0.5, 0.5, 0.5));
    }
  }
}
